input.content:
:root {
  --ink: #0a0d18;
  --gold: #e8c66a;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #05070f;
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  font-family: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #f3efe2;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
  touch-action: none;
}

#app {
  position: fixed;
  inset: 0;
  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px) env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
  background:
    radial-gradient(120% 90% at 50% 0%, #16203c 0%, #080b16 55%, #05070f 100%);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  outline: none;
}

#boot {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: radial-gradient(120% 90% at 50% 30%, #16203c 0%, #080b16 60%, #05070f 100%);
  transition: opacity 380ms ease;
  z-index: 10;
}

#boot.hide {
  opacity: 0;
  pointer-events: none;
}

#boot h1 {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(20px, 5.4vw, 44px);
  letter-spacing: 0.16em;
  font-weight: 600;
  color: #f2e3b6;
  text-shadow: 0 0 22px rgba(232, 198, 106, 0.45);
  text-align: center;
  padding: 0 16px;
}

#boot p {
  margin: 8px 0 0;
  font-size: 13px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #7d8bb0;
}

.boot-sword {
  font-size: 46px;
  color: var(--gold);
  filter: drop-shadow(0 0 16px rgba(232, 198, 106, 0.5));
  animation: float 2.6s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.noscript {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background: #080b16;
  color: #f3efe2;
  z-index: 20;
  margin: 0;
  padding: 24px;
  text-align: center;
}

/* La Espada Celestial — utilidades comunes */
(function () {
  const EG = (window.EG = window.EG || {});

  EG.clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  EG.lerp = (a, b, t) => a + (b - a) * t;
  EG.rnd = (a, b) => (b === undefined ? Math.random() * (a === undefined ? 1 : a) : a + Math.random() * (b - a));
  EG.rndi = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
  EG.pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
  EG.chance = (p) => Math.random() < p;
  EG.dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  EG.easeOut = (t) => 1 - Math.pow(1 - EG.clamp(t, 0, 1), 3);
  EG.fmt = (n) => Math.round(n).toLocaleString('es-ES');

  EG.shuffle = (arr) => {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };

  EG.pad2 = (n) => String(n).padStart(2, '0');

  EG.clock = (seconds) => {
    const s = Math.floor(seconds);
    return EG.pad2(Math.floor(s / 3600)) + ':' + EG.pad2(Math.floor((s % 3600) / 60)) + ':' + EG.pad2(s % 60);
  };

  // Guardado local tolerante a fallos (modo privado, cuota, etc.)
  const PREFIX = 'lec.';
  EG.store = {
    get(key, fallback) {
      try {
        const raw = localStorage.getItem(PREFIX + key);
        return raw ? JSON.parse(raw) : fallback;
      } catch (err) {
        return fallback;
      }
    },
    set(key, value) {
      try {
        localStorage.setItem(PREFIX + key, JSON.stringify(value));
        return true;
      } catch (err) {
        return false;
      }
    },
    remove(key) {
      try { localStorage.removeItem(PREFIX + key); } catch (err) { /* noop */ }
    },
  };

  EG.textWrap = (ctx, text, maxWidth) => {
    const words = String(text).split(/\s+/);
    const lines = [];
    let line = '';
    for (const word of words) {
      const test = line ? line + ' ' + word : word;
      if (ctx.measureText(test).width > maxWidth && line) {
        lines.push(line);
        line = word;
      } else {
        line = test;
      }
    }
    if (line) lines.push(line);
    return lines;
  };

  EG.roundRect = (ctx, x, y, w, h, r) => {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  };

  EG.alpha = (hex, a) => {
    const h = hex.replace('#', '');
    const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  };
})();

/* Entrada unificada: teclado + pantalla táctil + ratón */
(function () {
  const EG = window.EG;

  const KEYMAP = {
    ArrowUp: 'up', Up: 'up', w: 'up', W: 'up',
    ArrowDown: 'down', Down: 'down', s: 'down', S: 'down',
    ArrowLeft: 'left', Left: 'left', a: 'left', A: 'left',
    ArrowRight: 'right', Right: 'right', d: 'right', D: 'right',
    Enter: 'ok', ' ': 'ok', z: 'ok', Z: 'ok', e: 'ok', E: 'ok',
    Escape: 'back', x: 'back', X: 'back', Backspace: 'back',
    m: 'menu', M: 'menu', Tab: 'menu',
  };

  const Input = {
    keys: new Set(),
    just: new Set(),
    taps: [],
    ptrs: new Map(),
    onGesture: null,
    canvas: null,

    bind(canvas) {
      this.canvas = canvas;
      window.addEventListener('keydown', (e) => {
        const action = KEYMAP[e.key];
        if (!action) return;
        if (e.key === ' ' || e.key === 'Tab' || e.key.startsWith('Arrow')) e.preventDefault();
        if (!this.keys.has(action)) this.just.add(action);
        this.keys.add(action);
        this.gesture();
      });
      window.addEventListener('keyup', (e) => {
        const action = KEYMAP[e.key];
        if (action) this.keys.delete(action);
      });
      window.addEventListener('blur', () => {
        this.keys.clear();
        this.ptrs.clear();
      });

      const rectOf = () => canvas.getBoundingClientRect();
      const point = (e) => {
        const r = rectOf();
        return { x: e.clientX - r.left, y: e.clientY - r.top, id: e.pointerId };
      };

      canvas.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        const p = point(e);
        this.ptrs.set(p.id, p);
        this.taps.push({ x: p.x, y: p.y, id: p.id });
        try { canvas.setPointerCapture(p.id); } catch (err) { /* noop */ }
        this.gesture();
        if (this.gesturePulse) this.gesturePulse();
      }, { passive: false });

      canvas.addEventListener('pointermove', (e) => {
        const p = this.ptrs.get(e.pointerId);
        if (!p) return;
        const q = point(e);
        p.x = q.x; p.y = q.y;
      });

      const release = (e) => {
        this.ptrs.delete(e.pointerId);
      };
      canvas.addEventListener('pointerup', release);
      canvas.addEventListener('pointercancel', release);
      canvas.addEventListener('lostpointercapture', release);
      canvas.addEventListener('contextmenu', (e) => e.preventDefault());
      document.addEventListener('contextmenu', (e) => e.preventDefault());
    },

    gesture() {
      if (this.onGesture) this.onGesture();
    },

    down(action) {
      return this.keys.has(action);
    },
    pressed(action) {
      return this.just.has(action);
    },
    tapAt(x, y, rect) {
      return x >= rect.x && y >= rect.y && x <= rect.x + rect.w && y <= rect.y + rect.h;
    },
    firstTapIn(rect) {
      return this.taps.find((t) => this.tapAt(t.x, t.y, rect)) || null;
    },
    heldIn(rect) {
      for (const p of this.ptrs.values()) {
        if (this.tapAt(p.x, p.y, rect)) return p;
      }
      return null;
    },
    heldDirection() {
      if (this.down('up')) return 'up';
      if (this.down('down')) return 'down';
      if (this.down('left')) return 'left';
      if (this.down('right')) return 'right';
      return null;
    },
    endFrame() {
      this.just.clear();
      this.taps.length = 0;
    },
    reset() {
      this.keys.clear();
      this.ptrs.clear();
      this.taps.length = 0;
      this.just.clear();
    },
  };

  EG.Input = Input;
})();

/* Audio procedural: música y efectos sin archivos externos (WebAudio) */
(function () {
  const EG = window.EG;
  const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12); // MIDI -> Hz
  const N = { C: 0, Cs: 1, D: 2, Ds: 3, E: 4, F: 5, Fs: 6, G: 7, Gs: 8, A: 9, As: 10, B: 11 };
  const midi = (name, oct) => 12 * (oct + 1) + N[name];

  const TRACKS = {
    title: {
      bpm: 76,
      lead: [midi('A', 4), midi('C', 5), midi('E', 5), midi('D', 5), midi('C', 5), midi('A', 4), midi('G', 4), midi('A', 4)],
      bass: [midi('A', 2), midi('F', 2), midi('C', 3), midi('G', 2)],
      wave: 'triangle',
      gain: 0.05,
      sparkle: true,
    },
    village: {
      bpm: 104,
      lead: [midi('C', 5), midi('E', 5), midi('G', 5), midi('E', 5), midi('F', 5), midi('A', 5), midi('G', 5), midi('E', 5)],
      bass: [midi('C', 3), midi('F', 3), midi('G', 3), midi('C', 3)],
      wave: 'triangle',
      gain: 0.045,
    },
    field: {
      bpm: 118,
      lead: [midi('D', 5), midi('F', 5), midi('A', 5), midi('G', 5), midi('F', 5), midi('D', 5), midi('C', 5), midi('D', 5)],
      bass: [midi('D', 3), midi('A', 2), midi('B', 2), midi('G', 2)],
      wave: 'square',
      gain: 0.032,
    },
    dark: {
      bpm: 92,
      lead: [midi('A', 4), midi('G', 4), midi('E', 4), midi('G', 4), midi('F', 4), midi('E', 4), midi('D', 4), midi('E', 4)],
      bass: [midi('A', 2), midi('F', 2), midi('D', 2), midi('E', 2)],
      wave: 'sawtooth',
      gain: 0.026,
    },
    battle: {
      bpm: 150,
      lead: [midi('E', 5), midi('E', 5), midi('G', 5), midi('A', 5), midi('E', 5), midi('D', 5), midi('C', 5), midi('B', 4)],
      bass: [midi('E', 3), midi('E', 3), midi('C', 3), midi('D', 3)],
      wave: 'square',
      gain: 0.03,
    },
    boss: {
      bpm: 164,
      lead: [midi('D', 5), midi('Ds', 5), midi('D', 5), midi('A', 4), midi('As', 4), midi('A', 4), midi('F', 4), midi('G', 4)],
      bass: [midi('D', 2), midi('D', 2), midi('As', 2), midi('A', 2)],
      wave: 'sawtooth',
      gain: 0.03,
    },
    ending: {
      bpm: 70,
      lead: [midi('C', 5), midi('G', 5), midi('A', 5), midi('E', 5), midi('F', 5), midi('C', 6), midi('G', 5), midi('C', 6)],
      bass: [midi('C', 3), midi('A', 2), midi('F', 2), midi('G', 2)],
      wave: 'triangle',
      gain: 0.05,
    },
  };

  const Audio = {
    ctx: null,
    master: null,
    musicGain: null,
    enabled: true,
    trackName: null,
    timer: null,
    step: 0,
    nextTime: 0,
    noiseBuf: null,

    init() {
      if (this.ctx) {
        if (this.ctx.state === 'suspended') this.ctx.resume();
        return;
      }
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.9;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = this.enabled ? 1 : 0;
      this.musicGain.connect(this.master);

      const len = Math.floor(this.ctx.sampleRate * 0.4);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
      this.noiseBuf = buf;
    },

    setEnabled(on) {
      this.enabled = on;
      if (this.musicGain && this.ctx) {
        this.musicGain.gain.setTargetAtTime(on ? 1 : 0, this.ctx.currentTime, 0.05);
      }
    },

    tone(freq, dur, opts) {
      if (!this.ctx || !this.enabled) return;
      const o = opts || {};
      const t = this.ctx.currentTime + (o.delay || 0);
      const osc = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      osc.type = o.wave || 'square';
      osc.frequency.setValueAtTime(freq, t);
      if (o.slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, o.slide), t + dur);
      const vol = o.vol === undefined ? 0.12 : o.vol;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(g);
      g.connect(o.dest || this.master);
      osc.start(t);
      osc.stop(t + dur + 0.02);
    },

    noise(dur, opts) {
      if (!this.ctx || !this.enabled || !this.noiseBuf) return;
      const o = opts || {};
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      const g = this.ctx.createGain();
      const f = this.ctx.createBiquadFilter();
      f.type = o.filter || 'lowpass';
      f.frequency.value = o.freq || 1200;
      g.gain.value = o.vol === undefined ? 0.15 : o.vol;
      src.connect(f); f.connect(g); g.connect(this.master);
      src.start();
      src.stop(this.ctx.currentTime + dur);
    },

    sfx(name) {
      if (!this.ctx || !this.enabled) return;
      switch (name) {
        case 'cursor':
          this.tone(660, 0.05, { wave: 'square', vol: 0.05 });
          break;
        case 'select':
          this.tone(880, 0.07, { wave: 'square', vol: 0.07 });
          this.tone(1320, 0.09, { wave: 'square', vol: 0.05, delay: 0.05 });
          break;
        case 'cancel':
          this.tone(320, 0.1, { wave: 'square', vol: 0.06, slide: 190 });
          break;
        case 'hit':
          this.noise(0.16, { vol: 0.22, freq: 900 });
          this.tone(140, 0.12, { wave: 'square', vol: 0.12, slide: 70 });
          break;
        case 'crit':
          this.noise(0.2, { vol: 0.26, freq: 1600 });
          this.tone(880, 0.12, { wave: 'sawtooth', vol: 0.1, slide: 220 });
          break;
        case 'magic':
          this.tone(520, 0.28, { wave: 'triangle', vol: 0.08, slide: 1400 });
          this.tone(780, 0.24, { wave: 'sine', vol: 0.06, slide: 2100, delay: 0.05 });
          break;
        case 'heal':
          this.tone(660, 0.18, { wave: 'sine', vol: 0.09 });
          this.tone(990, 0.24, { wave: 'sine', vol: 0.07, delay: 0.08 });
          break;
        case 'level':
          [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.18, { wave: 'square', vol: 0.07, delay: i * 0.09 }));
          break;
        case 'coin':
          this.tone(1046, 0.08, { wave: 'square', vol: 0.06 });
          this.tone(1568, 0.14, { wave: 'square', vol: 0.05, delay: 0.06 });
          break;
        case 'chest':
          this.tone(392, 0.1, { wave: 'triangle', vol: 0.08 });
          this.tone(587, 0.1, { wave: 'triangle', vol: 0.08, delay: 0.1 });
          this.tone(784, 0.22, { wave: 'triangle', vol: 0.08, delay: 0.2 });
          break;
        case 'save':
          this.tone(523, 0.12, { wave: 'sine', vol: 0.08 });
          this.tone(784, 0.22, { wave: 'sine', vol: 0.08, delay: 0.1 });
          break;
        case 'flee':
          this.tone(300, 0.2, { wave: 'square', vol: 0.06, slide: 800 });
          break;
        case 'gameover':
          [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.35, { wave: 'triangle', vol: 0.09, delay: i * 0.18 }));
          break;
        case 'victory':
          [523, 659, 784, 1046, 1318].forEach((f, i) => this.tone(f, 0.3, { wave: 'square', vol: 0.07, delay: i * 0.11 }));
          break;
        case 'portal':
          this.tone(200, 0.4, { wave: 'sine', vol: 0.09, slide: 1200 });
          break;
        default:
          break;
      }
    },

    music(name) {
      if (this.trackName === name) return;
      this.trackName = name;
      this.step = 0;
      this.stopTimer();
      if (!this.ctx || !TRACKS[name]) return;
      this.nextTime = this.ctx.currentTime + 0.08;
      this.timer = setInterval(() => this.schedule(), 60);
      this.schedule();
    },

    stopTimer() {
      if (this.timer) clearInterval(this.timer);
      this.timer = null;
    },

    schedule() {
      if (!this.ctx) return;
      if (this.ctx.state !== 'running') return;
      if (this.ctx.currentTime > this.nextTime + 1.2) this.nextTime = this.ctx.currentTime + 0.1;
      const track = TRACKS[this.trackName];
      if (!track) return;
      const beat = 60 / track.bpm;
      const lookahead = this.ctx.currentTime + 0.35;
      while (this.nextTime < lookahead) {
        const t = this.nextTime - this.ctx.currentTime;
        const lead = track.lead[this.step % track.lead.length];
        const bass = track.bass[Math.floor(this.step / 2) % track.bass.length];
        this.playNote(lead, beat * 0.9, t, track.wave, track.gain, true);
        if (this.step % 2 === 0) this.playNote(bass, beat * 1.7, t, 'triangle', track.gain * 1.25, false);
        if (track.sparkle && this.step % 4 === 2) this.playNote(lead + 12, beat * 1.4, t + beat * 0.5, 'sine', track.gain * 0.5, false);
        this.step++;
        this.nextTime += beat;
      }
    },

    playNote(freq, dur, delay, wave, vol, lead) {
      if (!this.ctx) return;
      const t = this.ctx.currentTime + delay;
      const osc = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      osc.type = wave;
      osc.frequency.value = freq;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(vol, t + 0.03);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(g);
      g.connect(lead ? this.musicGain : this.musicGain);
      osc.start(t);
      osc.stop(t + dur + 0.05);
    },

    stopMusic() {
      this.trackName = null;
      this.stopTimer();
    },
  };

  EG.Audio = Audio;
})();

