    box(g, 10, 16, 10, 7, 'f');
    hline(g, 16, 1, 9, 'W');
    hline(g, 16, 20, 28, 'W');
    vline(g, 9, 1, 16, 'W');
    vline(g, 20, 1, 16, 'W');
    // salas laterales
    box(g, 1, 10, 8, 6, 'f');
    g[13][9] = 'f';
    box(g, 21, 10, 8, 6, 'f');
    g[13][20] = 'f';
    // salón del trono (norte)
    g[9][9] = 'D'; g[9][20] = 'D';
    box(g, 10, 1, 10, 8, 'f');
    box(g, 12, 2, 6, 4, 'u');
    g[2][15] = 'D'; // puerta al trono
    // decoración
    scatter(g, 13, 'p', [[11, 3], [18, 3], [11, 7], [18, 7], [12, 20], [17, 20], [4, 12], [25, 12]]);
    scatter(g, 14, 'C', [[2, 11], [27, 11], [6, 18], [23, 18], [15, 6]]);
    // entrada
    g[23][15] = 'D';
    g[22][15] = 'f';

    M.castillo = {
      name: 'Castillo del Eclipse', w: 30, h: 24, rows: rows(g), bgm: 'dark', safe: false,
      tint: 'rgba(35,10,45,0.26)',
      spawn: [15, 22],
