cd /home/runner/work/PlayGround/PlayGround && node -e '
global.window={}; global.window.EG={};
const fs=require("fs");
eval(fs.readFileSync("js/maps.js","utf8"));
const M=window.EG.maps, U=window.EG.mapUtil;
let bad=[];
for (const [k,m] of Object.entries(M)) {
  if (m.rows.length!==m.h) bad.push(k+": rows "+m.rows.length+" != h "+m.h);
  m.rows.forEach((r,i)=>{ if(r.length!==m.w) bad.push(k+": row "+i+" len "+r.length+" != w "+m.w); });
  const walk=(x,y)=>!U.isSolid(m,x,y);
  const check=(tag,x,y)=>{ if(!walk(x,y)) bad.push(`${k}: ${tag} at ${x},${y} is solid (${U.charAt(m,x,y)})`); };
  if(!walk(m.spawn[0],m.spawn[1])) bad.push(`${k}: spawn solid`);
  (m.npcs||[]).forEach(n=>check("npc "+n.id,n.x,n.y));
  (m.chests||[]).forEach(c=>check("chest "+c.id,c.x,c.y));
  (m.signs||[]).forEach(s=>check("sign",s.x,s.y));
  (m.flowers||[]).forEach(f=>check("flower "+f.id,f.x,f.y));
  (m.portals||[]).forEach(p=>{for(let y=p.y;y<p.y+p.h;y++)for(let x=p.x;x<p.x+p.w;x++)check("portal "+p.to,x,y);});
  (m.triggers||[]).forEach(t=>{for(let y=t.y;y<t.y+t.h;y++)for(let x=t.x;x<t.x+t.w;x++)check("trigger "+t.id,x,y);});
  // connectivity desde spawn
  const seen=new Set(), q=[m.spawn];
  while(q.length){const [x,y]=q.pop(); const kk=x+","+y; if(seen.has(kk))continue; if(!walk(x,y))continue; if(x<0||y<0||x>=m.w||y>=m.h)continue; seen.add(kk);
    q.push([x+1,y],[x-1,y],[x,y+1],[x,y-1]);}
  for (const [tag,x,y] of [...(m.npcs||[]).map(n=>["npc "+n.id,n.x,n.y]),...(m.chests||[]).map(c=>["chest "+c.id,c.x,c.y]),...(m.triggers||[]).map(t=>["trigger "+t.id,t.x,t.y])]) {
    if(!seen.has(x+","+y)) bad.push(`${k}: ${tag} inalcanzable desde spawn`);
  }
  console.log(k, m.w+"x"+m.h, "walkable", seen.size);
}
console.log(bad.length? "PROBLEMAS:\n"+bad.join("\n") : "OK: mapas consistentes");
'

