/* Núcleo: estado, bucle, guardado, menús, tienda y transiciones */
(function () {
  const EG = window.EG;
  const D = () => EG.data;

  const SAVE_SLOTS = ['slot1', 'slot2', 'slot3'];

  const game = {
    canvas: null,
    ctx: null,
    dpr: 1,
    last: 0,
    mode: 'title',
    state: null,
    overlays: [],
    touchUI: false,
    titleFocus: 0,
    titleTime: 0,
    shake: 0,
    fade: 0,
    fadeCb: null,
    endingTime: 0,
    newGamePending: false,

    init() {
      this.canvas = document.getElementById('game');
      this.ctx = this.canvas.getContext('2d');
      if (!this.ctx) {
        document.getElementById('boot-msg').textContent = 'Tu navegador no soporta canvas.';
        return;
      }
      EG.art.init();
      EG.Input.bind(this.canvas);
      this.touchUI = ('ontouchstart' in window) || navigator.maxTouchPoints > 0 || window.matchMedia('(pointer: coarse)').matches;

      const settings = EG.store.get('settings', { music: true, sfx: true });
      EG.Audio.init();
      EG.Audio.setMusic(settings.music);
      EG.Audio.setSfx(settings.sfx);
      this.settings = settings;

      EG.Input.onGesture = () => {
        EG.Audio.init();
        if (this.mode !== 'title' && this.state) {
          const map = EG.maps[this.state.zone];
          if (map) EG.Audio.music(map.bgm);
        } else if (this.mode === 'title') {
          EG.Audio.music('title');
        } else if (this.mode === 'battle') {
          // la música de combate ya está fijada
        }
      };

      this.resize();
      window.addEventListener('resize', () => this.resize());
      window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 250));
      const trail = () => {
        this.resize();
        document.getElementById('boot').classList.add('hide');
        setTimeout(() => {
          const b = document.getElementById('boot');
          if (b && b.parentNode) b.parentNode.removeChild(b);
        }, 500);
        EG.Audio.music('title');
      };
      trail();
      this.last = performance.now();
      requestAnimationFrame((t) => this.frame(t));
    },

    resize() {
      const rect = this.canvas.getBoundingClientRect();
      const w = Math.max(240, Math.round(rect.width));
      const h = Math.max(240, Math.round(rect.height));
      this.dpr = Math.min(2, window.devicePixelRatio || 1);
      this.canvas.width = Math.round(w * this.dpr);
      this.canvas.height = Math.round(h * this.dpr);
      this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      EG.UI.setCtx(this.ctx, w, h);
      if (EG.world && EG.world.map) EG.world.snapCamera();
    },

    frame(ts) {
      const dt = Math.min(0.05, Math.max(0, (ts - this.last) / 1000));
      this.last = ts;
      this.update(dt);
      this.draw();
      EG.Input.endFrame();
      requestAnimationFrame((t) => this.frame(t));
    },

    /* ------------------------------- UPDATE ------------------------------- */

    update(dt) {
      EG.UI.processTaps();
      EG.UI.beginFrame();
      this.shake = Math.max(0, this.shake - dt * 20);

      const top = this.overlays[this.overlays.length - 1];
      if (top) {
        top.update(dt);
      } else if (this.mode === 'title') {
        this.updateTitle(dt);
      } else if (this.mode === 'world') {
        EG.world.update(dt);
      } else if (this.mode === 'battle') {
        EG.battle.update(dt);
      } else if (this.mode === 'ending') {
        this.updateEnding(dt);
      }
      EG.UI.drawToast(dt);
    },

    /* -------------------------------- DRAW -------------------------------- */

    draw() {
      const ctx = this.ctx;
      const W = EG.UI.W, H = EG.UI.H;
      ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);
      ctx.imageSmoothingEnabled = false;

      if (this.mode === 'title') {
        this.drawTitle();
      } else if (this.mode === 'battle' && EG.battle.active) {
        EG.battle.draw();
      } else if (this.mode === 'ending') {
        this.drawEnding();
      } else if (this.mode === 'world') {
        EG.world.draw();
      } else {
        ctx.fillStyle = '#05070f';
        ctx.fillRect(0, 0, W, H);
      }

      for (const o of this.overlays) o.draw();
      if (this.fade > 0) {
        ctx.save();
        ctx.fillStyle = `rgba(3,5,12,${this.fade})`;
        ctx.fillRect(0, 0, W, H);
        ctx.restore();
      }
    },

    /* -------------------------------- TÍTULO -------------------------------- */

    updateTitle(dt) {
      this.titleTime += dt;
      const saves = this.saveList();
      const items = this.titleItems(saves);
      if (EG.Input.pressed('up')) { this.titleFocus = (this.titleFocus + items.length - 1) % items.length; EG.Audio.sfx('cursor'); }
      if (EG.Input.pressed('down')) { this.titleFocus = (this.titleFocus + 1) % items.length; EG.Audio.sfx('cursor'); }
      if (EG.Input.pressed('ok')) { EG.Audio.sfx('select'); items[this.titleFocus].action(); }
    },

    titleItems(saves) {
      const items = [];
      if (saves.length) {
        items.push({ label: 'Continuar', sub: 'Retoma la última partida guardada', action: () => this.continueGame() });
      }
      items.push({ label: 'Nueva partida', sub: 'La Espada Celestial te espera', action: () => this.newGamePrompt() });
      items.push({ label: 'Cómo jugar', sub: 'Controles y consejos', action: () => this.showHowToPlay() });
      items.push({ label: 'Ajustes', sub: 'Sonido y datos', action: () => this.openSettings() });
      return items;
    },

    drawTitle() {
      const UI = EG.UI, ctx = UI.ctx;
      const W = UI.W, H = UI.H;
      const t = this.titleTime;

      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, '#0a1226');
      g.addColorStop(0.5, '#0d1730');
      g.addColorStop(1, '#060a14');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);

      // estrellas
      for (let i = 0; i < 70; i++) {
        const x = (i * 97.13) % W;
        const y = ((i * 53.7) % (H * 0.62));
        const a = 0.25 + 0.65 * Math.abs(Math.sin(t * 0.8 + i));
        ctx.fillStyle = `rgba(220,232,255,${a * 0.7})`;
        ctx.fillRect(x, y, i % 9 === 0 ? 2 : 1, i % 9 === 0 ? 2 : 1);
      }

      // luna
      const mx = W * 0.72, my = H * 0.2, mr = Math.min(W, H) * 0.11;
      ctx.save();
      const glow = ctx.createRadialGradient(mx, my, mr * 0.4, mx, my, mr * 2.6);
      glow.addColorStop(0, 'rgba(240,232,200,0.35)');
      glow.addColorStop(1, 'rgba(240,232,200,0)');
      ctx.fillStyle = glow;
      ctx.fillRect(mx - mr * 3, my - mr * 3, mr * 6, mr * 6);
      ctx.beginPath();
      ctx.arc(mx, my, mr, 0, Math.PI * 2);
      ctx.fillStyle = '#eae0c2';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(mx - mr * 0.35, my - mr * 0.2, mr * 0.18, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(190,180,150,0.55)';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(mx + mr * 0.28, my + mr * 0.3, mr * 0.12, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // montañas
      ctx.save();
      ctx.fillStyle = '#0a1020';
      ctx.beginPath();
      ctx.moveTo(0, H * 0.68);
      ctx.lineTo(W * 0.16, H * 0.5);
      ctx.lineTo(W * 0.32, H * 0.66);
      ctx.lineTo(W * 0.5, H * 0.46);
      ctx.lineTo(W * 0.68, H * 0.64);
      ctx.lineTo(W * 0.85, H * 0.52);
      ctx.lineTo(W, H * 0.66);
      ctx.lineTo(W, H);
      ctx.lineTo(0, H);
      ctx.closePath();
      ctx.fill();
      ctx.restore();

      // espada clavada
      const sx = W * 0.24, sy = H * 0.44;
      ctx.save();
      ctx.translate(sx, sy);
      ctx.rotate(-0.06);
      const len = Math.min(H * 0.42, 300);
      const glow2 = ctx.createLinearGradient(0, -len, 0, 0);
      glow2.addColorStop(0, 'rgba(255,246,214,0.9)');
      glow2.addColorStop(1, 'rgba(200,190,150,0.15)');
      ctx.strokeStyle = glow2;
      ctx.lineWidth = Math.max(4, W * 0.008);
      ctx.beginPath();
      ctx.moveTo(0, -len);
      ctx.lineTo(0, 0);
      ctx.stroke();
      ctx.fillStyle = '#d8c88a';
      ctx.fillRect(-Math.max(14, W * 0.026), -len * 0.14, Math.max(28, W * 0.052), Math.max(6, W * 0.011));
      ctx.fillStyle = '#8a6a2e';
      ctx.fillRect(-3, 0, 6, len * 0.2);
      for (let i = 0; i < 5; i++) {
        const ang = t * 1.4 + i * 1.26;
        ctx.globalAlpha = 0.25 + 0.25 * Math.sin(t * 2 + i);
        ctx.fillStyle = '#fff3c4';
        ctx.fillRect(Math.cos(ang) * (26 + i * 8), -len * 0.5 + Math.sin(ang * 1.3) * 18, 2, 2);
      }
      ctx.restore();

      // título
      const titleSize = EG.clamp(W * 0.062, 24, 54);
      const ty = H * 0.16;
      ctx.save();
      ctx.textAlign = 'center';
      ctx.font = `600 ${titleSize}px ${UI.serif}`;
      ctx.shadowColor = 'rgba(232,198,106,0.45)';
      ctx.shadowBlur = 26;
      ctx.fillStyle = '#f2e3b6';
      ctx.fillText('LA ESPADA', W / 2, ty);
      ctx.fillText('CELESTIAL', W / 2, ty + titleSize * 1.1);
      ctx.restore();
      UI.txt('Un RPG de luz y eclipse', W / 2, ty + titleSize * 2.28, {
        size: EG.clamp(W * 0.017, 11, 15), color: 'rgba(200,214,245,0.6)', align: 'center', serif: true,
      });

      // menú
      const items = this.titleItems(this.saveList());
      const bw = Math.min(W - 48, 340);
      const bh = 46;
      const startY = Math.max(H * 0.56, ty + titleSize * 2.7);
      items.forEach((it, i) => {
        const y = startY + i * (bh + 8);
        if (y + bh > H - 24) return;
        UI.button((W - bw) / 2, y, bw, bh, it.label, {
          focused: this.titleFocus === i,
          size: 15,
          sub: this.touchUI ? null : it.sub,
          onPick: () => { this.titleFocus = i; EG.Audio.sfx('select'); it.action(); },
        });
      });

      UI.txt('v1.0 · hecho para jugar aquí, no para parecerlo', W / 2, H - 12, {
        size: 9.5, color: 'rgba(160,175,205,0.35)', align: 'center', baseline: 'bottom',
      });
    },

    showHowToPlay() {
      EG.UI.dialog({
        pages: [
          { who: 'Cómo jugar', text: 'Muévete con las flechas, WASD o el panel táctil. Pulsa A (o Z/Enter) para hablar, abrir cofres y confirmar.' },
          { who: 'Cómo jugar', text: 'B (o X/Esc) abre el menú. En combate, elige Atacar, Habilidad, Objeto, Defender o Huir. Las debilidades elementales hacen mucho daño.' },
          { who: 'Cómo jugar', text: 'La hierba alta y las mazmorras tienen encuentros. Descansa en la posada para curarte y guardar. El juego también guarda solo al cambiar de zona.' },
          { who: 'Cómo jugar', text: 'Objetivo: reunir los tres fragmentos de la Espada Celestial y derrotar a Lord Eclipse antes de que apague la luna.' },
        ],
      });
    },

    /* ------------------------------ PARTIDA ------------------------------ */

    newGamePrompt() {
      const existing = this.saveList();
      if (!existing.length) return this.newGame();
      EG.UI.dialog({
        pages: [{
          who: 'Nueva partida',
          text: 'Ya hay partidas guardadas. ¿Empezar de cero? No se borrarán tus guardados.',
          choices: [
            { label: 'Empezar de cero', action: () => this.newGame() },
            { label: 'Cancelar', action: () => {} },
          ],
        }],
      });
    },

    newGame() {
      this.state = {
        version: 1,
        zone: 'alba', tx: 14, ty: 17, dir: 'up',
        gold: 60,
        items: Object.assign({}, D().STARTER_ITEMS),
        party: [D().newActor('kael')],
        flags: {},
        quests: { main: 'active', flores: 'locked', colmillos: 'locked' },
        chests: {}, collected: {}, triggers: {},
        fragments: 0,
        playtime: 0, stepsSinceBattle: 0, wins: 0, deaths: 0,
        savedAt: 0,
      };
      this.mode = 'world';
      EG.world.enter('alba', 14, 17, 'up');
      this.overlays.length = 0;
      this.autoSave();
      EG.story.intro();
    },

    saveList() {
      const out = [];
      for (const slot of SAVE_SLOTS.concat(['auto'])) {
        const data = EG.store.get(slot, null);
        if (data && data.meta) out.push({ slot, meta: data.meta });
      }
      out.sort((a, b) => b.meta.savedAt - a.meta.savedAt);
      return out;
    },

    metaOf(state) {
      return {
        name: state.party[0] ? state.party[0].name : 'Kael',
        lvl: state.party[0] ? state.party[0].lvl : 1,
        zone: (EG.maps[state.zone] || {}).name || state.zone,
        playtime: state.playtime,
        fragments: state.fragments,
        savedAt: Date.now(),
        party: state.party.map((p) => p.name).join(', '),
      };
    },

    saveTo(slot) {
      if (!this.state) return false;
      this.state.savedAt = Date.now();
      const ok = EG.store.set(slot, { state: this.state, meta: this.metaOf(this.state) });
      if (ok) {
        EG.Audio.sfx('save');
        EG.UI.showToast('Partida guardada', 'gold');
      } else {
        EG.UI.showToast('No se pudo guardar', 'bad');
      }
      return ok;
    },

    autoSave() {
      if (!this.state) return;
      this.state.savedAt = Date.now();
      EG.store.set('auto', { state: this.state, meta: this.metaOf(this.state) });
    },

    continueGame() {
      const list = this.saveList();
      if (!list.length) return this.newGame();
      this.loadSlot(list[0].slot);
    },

    loadSlot(slot) {
      const data = EG.store.get(slot, null);
      if (!data || !data.state) { EG.UI.showToast('Guardado no válido', 'bad'); return; }
      const st = data.state;
      st.flags = st.flags || {};
      st.quests = st.quests || {};
      st.chests = st.chests || {};
      st.collected = st.collected || {};
      st.triggers = st.triggers || {};
      st.items = st.items || {};
      st.fragments = st.fragments || 0;
      this.state = st;
      this.mode = 'world';
      this.overlays.length = 0;
      EG.Audio.sfx('save');
      EG.world.enter(st.zone || 'alba', st.tx || 14, st.ty || 17, st.dir || 'down');
      EG.UI.showToast(`Partida cargada · ${EG.clock(st.playtime || 0)}`);
    },

    travel(zone, tx, ty) {
      EG.world.enter(zone, tx, ty, 'down');
      this.autoSave();
    },

    revertStep() {
      const p = EG.world.player;
      if (!p) return;
      const map = EG.world.map;
      const deltas = { up: [0, 1], down: [0, -1], left: [1, 0], right: [-1, 0] };
      const [dx, dy] = deltas[p.dir] || [0, 0];
      const nx = p.tx + dx, ny = p.ty + dy;
      if (!map || EG.world.blockerAt(nx, ny)) return;
      p.tx = nx; p.ty = ny;
      p.px = nx * 16; p.py = ny * 16;
      p.moving = false;
      this.state.tx = nx; this.state.ty = ny;
    },

    portalUnlocked(portal) {
      const need = portal.need;
      if (!need) return true;
      if (need.fragments && this.state.fragments < need.fragments) return false;
      if (need.item && this.countItem(need.item) <= 0) return false;
      if (need.flag && !this.state.flags[need.flag]) return false;
      return true;
    },

    /* ------------------------------ INVENTARIO ------------------------------ */

    countItem(id) {
      return (this.state.items[id] || 0);
    },

    addItem(id, n) {
      if (!D().ITEMS[id]) return false;
      const cur = this.state.items[id] || 0;
      const next = cur + (n === undefined ? 1 : n);
      if (next <= 0) delete this.state.items[id];
      else this.state.items[id] = next;
      return true;
    },

    consumables() {
      return Object.entries(this.state.items).filter(([id, n]) => {
        const it = D().ITEMS[id];
        return it && it.kind === 'consumible' && n > 0;
      }).map(([id]) => id);
    },

    equipmentInBag(kind) {
      return Object.entries(this.state.items)
        .filter(([id, n]) => {
          const it = D().ITEMS[id];
          return it && it.kind === kind && n > 0;
        })
        .map(([id, n]) => ({ id, n, item: D().ITEMS[id] }));
    },

    equip(actor, slot, itemId) {
      const current = actor.equip[slot];
      if (current) this.addItem(current, 1);
      if (itemId) this.addItem(itemId, -1);
      actor.equip[slot] = itemId || null;
      const stats = D().statsOf(actor);
      actor.hp = Math.min(actor.hp, stats.hp);
      actor.mp = Math.min(actor.mp, stats.mp);
      EG.Audio.sfx('select');
    },

    useItemOutside(id, actor) {
      const it = D().ITEMS[id];
      if (!it || it.kind !== 'consumible' || this.countItem(id) <= 0) return false;
      const stats = D().statsOf(actor);
      let did = false;
      if (it.use && it.use.hp) {
        const before = actor.hp;
        actor.hp = Math.min(stats.hp, actor.hp + it.use.hp);
        did = did || actor.hp > before;
      }
      if (it.use && it.use.mp) {
        const before = actor.mp;
        actor.mp = Math.min(stats.mp, actor.mp + it.use.mp);
        did = did || actor.mp > before;
      }
      if (it.use && it.use.cure) did = true;
      if (it.use && it.use.damage) return false;
      if (!did) {
        EG.UI.showToast('No tiene efecto ahora', 'bad');
        return false;
      }
      this.addItem(id, -1);
      EG.Audio.sfx('heal');
      EG.UI.showToast(`${actor.name} usa ${it.name}`);
      return true;
    },

    healParty() {
      for (const a of this.state.party) {
        const s = D().statsOf(a);
        a.hp = s.hp;
        a.mp = s.mp;
      }
    },

    leaderSprite() {
      const a = this.state && this.state.party[0];
      return a ? D().ACTORS[a.id].sprite : 'kael';
    },

    spriteOf(ref) {
      const a = ref && D().ACTORS[ref.id];
      return a ? a.sprite : 'kael';
    },

    /* ------------------------------- EVENTOS ------------------------------- */

    openChest(chest) {
      if (this.state.chests[chest.id]) {
        EG.story.say('', 'El cofre está vacío.');
        return;
      }
      this.state.chests[chest.id] = true;
      const loot = chest.loot || {};
      const lines = [];
      if (loot.gold) {
        this.state.gold += loot.gold;
        lines.push(`${loot.gold} de oro`);
      }
      if (loot.item) {
        this.addItem(loot.item, loot.count || 1);
        lines.push(`${D().ITEMS[loot.item].name}${loot.count > 1 ? ' ×' + loot.count : ''}`);
      }
      EG.Audio.sfx('chest');
      EG.UI.showToast('¡Has encontrado ' + (lines.join(' y ') || 'polvo') + '!', 'gold');
      EG.story.say('', 'Dentro hay: ' + (lines.join(' y ') || 'sólo polvo y telarañas') + '.');
    },

    startEncounter(enc) {
      const count = EG.chance(0.25) ? 2 : 1;
      const ids = [];
      for (let i = 0; i < count; i++) ids.push(EG.pick(enc.pool));
      this.startBattle(ids, { boss: false });
    },

    startBattle(ids, opts) {
      if (!this.state) return;
      this.mode = 'battle';
      this.overlays.length = 0;
      EG.battle.start(ids, opts || {});
      this.shake = 6;
    },

    endBattle(result, rewards, opts) {
      if (!this.state) return;
      const b = EG.battle.s;
      if (b && b.party) {
        b.party.forEach((c, i) => {
          const ref = this.state.party[i];
          if (!ref) return;
          ref.hp = Math.max(0, Math.round(c.hp));
          ref.mp = Math.max(0, Math.round(c.mp));
        });
      }
      this.mode = 'world';
      const map = EG.maps[this.state.zone];
      if (map) EG.Audio.music(map.bgm);

      if (result === 'lose') {
        const lost = Math.round(this.state.gold * 0.1);
        this.state.gold = Math.max(0, this.state.gold - lost);
        this.healParty();
        this.mode = 'world';
        EG.world.enter('posada', 6, 7, 'up');
        this.autoSave();
        EG.UI.showToast(`Has caído. Pierdes ${lost} de oro.`, 'bad');
        setTimeout(() => {
          EG.story.say('Bruno', 'Te trajeron de vuelta. Descansa; la luna no se apagará esta noche. Tus heridas están curadas, pero tu bolsa pesa menos.');
        }, 250);
        return;
      }

      if (result === 'win') {
        this.autoSave();
        if (rewards && rewards.levels && rewards.levels.length) {
          EG.Audio.sfx('level');
          const names = rewards.levels.map((l) => `${l.name} alcanza el nivel ${l.lvl}`);
          EG.UI.showToast(names.join(' · '), 'gold');
          const skills = rewards.levels.flatMap((l) => l.skills.map((s) => `${l.name}: ${D().SKILLS[s].name}`));
          if (skills.length) {
            setTimeout(() => {
              EG.story.say('', 'Nuevas habilidades: ' + skills.join(' · '));
            }, 350);
          }
        } else if (rewards) {
          EG.UI.showToast(`+${rewards.xp} EXP · +${rewards.gold} oro`, 'gold');
        }
        if (rewards && rewards.drops && rewards.drops.length) {
          const names = [...new Set(rewards.drops)].map((id) => D().ITEMS[id].name);
          EG.UI.showToast('Botín: ' + names.join(', '), 'gold');
        }
        if (opts && opts.onWin) opts.onWin(rewards);
        return;
      }

      if (result === 'flee') {
        EG.UI.showToast('Escapaste del combate');
      }
    },

    /* ------------------------------- MENÚS ------------------------------- */

    openOverlay(overlay) {
      this.overlays.push(overlay);
      return overlay;
    },

    closeOverlay(overlay) {
      const i = this.overlays.indexOf(overlay);
      if (i >= 0) this.overlays.splice(i, 1);
    },

    openFieldMenu() {
      const self = this;
      const items = () => [
        { label: 'Objetos', sub: `${self.state.party.length} aliados · ${Object.keys(self.state.items).length} tipos`, action: () => self.openItems() },
        { label: 'Equipo', sub: 'Armas, armaduras y accesorios', action: () => self.openEquip() },
        { label: 'Habilidades', sub: 'Consulta lo que sabe cada héroe', action: () => self.openSkills() },
        { label: 'Diario', sub: `Fragmentos ${self.state.fragments}/3`, action: () => self.openJournal() },
        { label: 'Guardar', sub: 'Tres ranuras + autoguardado', action: () => self.openSaveMenu() },
        { label: 'Ajustes', sub: 'Sonido y datos', action: () => self.openSettings() },
        { label: 'Volver', sub: '', action: () => {} },
      ];
      const partyInfo = this.state.party.map((a) => `${a.name} Nv${a.lvl}`).join(' · ');
      const overlay = EG.UI.listPanel({
        title: 'MENÚ',
        subtitle: `${partyInfo}   |   ${EG.fmt(this.state.gold)} oro   |   ${EG.clock(this.state.playtime)}`,
        items,
        footer: 'Los corazones de la espada laten en tu mochila.',
      });
      const origClose = overlay.close.bind(overlay);
      overlay.close = () => {
        if (this.overlays[this.overlays.length - 1] === overlay) origClose();
      };
    },

    openItems() {
      const self = this;
      const items = () => {
        const list = [];
        for (const [id, n] of Object.entries(self.state.items)) {
          const it = D().ITEMS[id];
          if (!it || n <= 0) continue;
          list.push({
            label: `${it.name} ×${n}`,
            sub: it.desc,
            right: it.kind === 'consumible' ? 'USAR' : it.kind.toUpperCase(),
            color: it.kind === 'clave' ? EG.COLORS.gold : EG.COLORS.ink,
            disabled: it.kind === 'clave',
            action: () => {
              if (it.kind !== 'consumible') return;
              self.pickAlly(`Usar ${it.name}`, (actor) => {
                if (self.useItemOutside(id, actor)) self.openItems();
              });
            },
          });
        }
        if (!list.length) list.push({ label: 'Mochila vacía', sub: 'Compra pociones en la herrería', disabled: true });
        return list;
      };
      EG.UI.listPanel({ title: 'OBJETOS', subtitle: `${EG.fmt(self.state.gold)} oro`, items, footer: 'A usar · B volver' });
    },

    pickAlly(title, cb) {
      const self = this;
      EG.UI.listPanel({
        title,
        subtitle: 'Elige un aliado',
        items: () => self.state.party.map((a) => {
          const s = D().statsOf(a);
          return {
            label: a.name,
            sub: `Nv ${a.lvl} · PV ${Math.round(a.hp)}/${s.hp} · PM ${Math.round(a.mp)}/${s.mp}`,
            right: `${Math.round((a.hp / s.hp) * 100)}%`,
            action: () => cb(a),
          };
        }),
      });
    },

    openEquip() {
      const self = this;
      EG.UI.listPanel({
        title: 'EQUIPO',
        subtitle: 'Elige a un héroe',
        items: () => self.state.party.map((a) => ({
          label: a.name,
          sub: `${D().ACTORS[a.id].role} · Nv ${a.lvl}`,
          action: () => self.openEquipSlots(a),
        })),
      });
    },

    openEquipSlots(actor) {
      const self = this;
      const slots = [['arma', 'Arma'], ['armadura', 'Armadura'], ['accesorio', 'Accesorio']];
      const items = () => slots.map(([slot, label]) => {
        const id = actor.equip[slot];
        const it = id ? D().ITEMS[id] : null;
        return {
          label,
          sub: it ? it.name : '— vacío —',
          right: it && it.stats ? statLine(it.stats) : '',
          action: () => self.openEquipPick(actor, slot),
        };
      });
      const s = D().statsOf(actor);
      EG.UI.listPanel({
        title: actor.name.toUpperCase(),
        subtitle: `ATQ ${s.atk} · DEF ${s.def} · MAG ${s.mag} · RES ${s.res} · VEL ${s.spd}`,
        items,
        footer: 'El equipo cambia tus estadísticas al instante.',
      });
    },

    openEquipPick(actor, slot) {
      const self = this;
      const kind = slot === 'arma' ? 'arma' : slot === 'armadura' ? 'armadura' : 'accesorio';
      EG.UI.listPanel({
        title: 'ELEGIR ' + slot.toUpperCase(),
        subtitle: 'Objetos en la mochila',
        items: () => {
          const list = self.equipmentInBag(kind).map((e) => ({
            label: `${e.item.name} ×${e.n}`,
            sub: e.item.desc,
            right: e.item.stats ? statLine(e.item.stats) : '',
            action: () => {
              self.equip(actor, slot, e.id);
              EG.UI.showToast(`${actor.name} equipa ${e.item.name}`);
              self.openEquipSlots(actor);
            },
          }));
          if (actor.equip[slot]) {
            list.unshift({
              label: 'Desequipar',
              sub: 'Devuelve el objeto a la mochila',
              action: () => {
                self.equip(actor, slot, null);
                self.openEquipSlots(actor);
              },
            });
          }
          if (!list.length) list.push({ label: 'Nada que equipar', sub: 'Compra en la herrería', disabled: true });
          return list;
        },
      });
    },

    openSkills() {
      const self = this;
      EG.UI.listPanel({
        title: 'HABILIDADES',
        subtitle: 'Elige a un héroe',
        items: () => self.state.party.map((a) => ({
          label: a.name,
          sub: `${a.skills.length} habilidades · Nv ${a.lvl}`,
          action: () => self.openSkillList(a),
        })),
      });
    },

    openSkillList(actor) {
      EG.UI.listPanel({
        title: actor.name.toUpperCase(),
        subtitle: `PM ${Math.round(actor.mp)}/${D().statsOf(actor).mp}`,
        items: () => actor.skills.map((id) => {
          const sk = D().SKILLS[id];
          return {
            label: sk.name,
            sub: sk.desc,
            right: `${sk.mp} PM`,
            action: () => {},
          };
        }),
      });
    },

    openJournal() {
      const self = this;
      EG.UI.listPanel({
        title: 'DIARIO',
        subtitle: `Fragmentos celestiales: ${self.state.fragments}/3`,
        items: () => EG.story.journal(self.state),
        footer: 'La luna recuerda cada paso que das.',
      });
    },

    openSaveMenu() {
      const self = this;
      EG.UI.listPanel({
        title: 'GUARDAR',
        subtitle: 'Elige una ranura',
        items: () => SAVE_SLOTS.map((slot, i) => {
          const data = EG.store.get(slot, null);
          const meta = data && data.meta;
          return {
            label: `Ranura ${i + 1}` + (meta ? ` · ${meta.name} Nv${meta.lvl}` : ' · vacía'),
            sub: meta ? `${meta.zone} · ${EG.clock(meta.playtime)} · ${new Date(meta.savedAt).toLocaleDateString('es-ES')}` : 'Guardar aquí',
            right: meta ? 'GUARDAR' : 'GUARDAR',
            action: () => {
              if (meta) {
                EG.UI.dialog({
                  pages: [{
                    who: 'Sobrescribir',
                    text: `¿Sobrescribir la ranura ${i + 1}?`,
                    choices: [
                      { label: 'Sí, guardar', action: () => { self.saveTo(slot); self.openSaveMenu(); } },
                      { label: 'Cancelar', action: () => {} },
                    ],
                  }],
                });
              } else {
                self.saveTo(slot);
                self.openSaveMenu();
              }
            },
          };
        }),
        footer: 'El autoguardado se actualiza al cambiar de zona.',
      });
    },

    openSettings() {
      const self = this;
      const settings = () => EG.store.get('settings', { music: true, sfx: true });
      EG.UI.listPanel({
        title: 'AJUSTES',
        subtitle: 'Se guardan en este dispositivo',
        items: () => {
          const st = settings();
          return [
            {
              label: 'Música',
              sub: st.music ? 'Activada' : 'Desactivada',
              right: st.music ? 'SÍ' : 'NO',
              action: () => {
                st.music = !st.music;
                EG.store.set('settings', st);
                EG.Audio.setMusic(st.music);
                EG.Audio.sfx('cursor');
                self.openSettings();
              },
            },
            {
              label: 'Efectos de sonido',
              sub: st.sfx ? 'Activados' : 'Desactivados',
              right: st.sfx ? 'SÍ' : 'NO',
              action: () => {
                st.sfx = !st.sfx;
                EG.store.set('settings', st);
                EG.Audio.setSfx(st.sfx);
                EG.Audio.sfx('cursor');
                self.openSettings();
              },
            },
            {
              label: 'Cómo jugar',
              sub: 'Controles, combate y guardado',
              action: () => self.showHowToPlay(),
            },
            {
              label: 'Borrar progreso guardado',
              sub: 'Elimina las tres ranuras y el autoguardado',
              color: '#e08585',
              action: () => {
                EG.UI.dialog({
                  pages: [{
                    who: 'Borrar datos',
                    text: '¿Borrar todas las partidas guardadas de este dispositivo? No se puede deshacer.',
                    choices: [
                      { label: 'Borrar todo', action: () => {
                        for (const s of SAVE_SLOTS.concat(['auto'])) EG.store.remove(s);
                        EG.UI.showToast('Datos borrados');
                      } },
                      { label: 'Cancelar', action: () => {} },
                    ],
                  }],
                });
              },
            },
            { label: 'Volver', sub: '', action: () => {} },
          ];
        },
      });
    },

    /* -------------------------------- TIENDA -------------------------------- */

    openShop(name, goods) {
      const self = this;
      let tab = 'buy';
      let focus = 0;
      let scroll = 0;
      const overlay = {
        modal: true,
        update(dt) {
          const list = this.list();
          if (EG.Input.pressed('left') || EG.Input.pressed('right')) {
            tab = tab === 'buy' ? 'sell' : 'buy';
            focus = 0; scroll = 0;
            EG.Audio.sfx('cursor');
          }
          if (EG.Input.pressed('up')) { focus = (focus + list.length - 1) % list.length; EG.Audio.sfx('cursor'); }
          if (EG.Input.pressed('down')) { focus = (focus + 1) % list.length; EG.Audio.sfx('cursor'); }
          if (EG.Input.pressed('ok')) {
            const it = list[focus];
            if (it) this.activate(it);
          }
          if (EG.Input.pressed('back')) { EG.Audio.sfx('cancel'); this.close(); }
        },
        list() {
          if (tab === 'buy') {
            return goods.map((id) => {
              const it = D().ITEMS[id];
              return { id, item: it, price: it.price, label: it.name, sub: it.desc, right: `${it.price} oro` };
            });
          }
          return Object.entries(self.state.items)
            .filter(([id, n]) => n > 0 && D().ITEMS[id] && D().ITEMS[id].kind !== 'clave')
            .map(([id, n]) => {
              const it = D().ITEMS[id];
              return { id, item: it, price: Math.floor(it.price * 0.5), label: `${it.name} ×${n}`, sub: it.desc, right: `+${Math.floor(it.price * 0.5)} oro` };
            });
        },
        activate(it) {
          if (tab === 'buy') {
            if (self.state.gold < it.price) { EG.Audio.sfx('cancel'); EG.UI.showToast('No tienes oro suficiente', 'bad'); return; }
            self.state.gold -= it.price;
            self.addItem(it.id, 1);
            EG.Audio.sfx('coin');
            EG.UI.showToast(`Compraste ${it.item.name}`);
            focus = Math.min(focus, this.list().length - 1);
          } else {
            if (self.countItem(it.id) <= 0) return;
            self.addItem(it.id, -1);
            self.state.gold += it.price;
            EG.Audio.sfx('coin');
            EG.UI.showToast(`Vendiste ${it.item.name} por ${it.price}`);
            focus = Math.min(focus, Math.max(0, this.list().length - 1));
          }
        },
        close() { self.closeOverlay(this); },
        draw() {
          const UI = EG.UI, ctx = UI.ctx;
          const W = UI.W, H = UI.H;
          UI.backdrop(0.75);
          const m = Math.min(18, W * 0.04);
          const bw = W - m * 2, bh = H - m * 2 - 10;
          const bx = m, by = m;
          UI.panel(bx, by, bw, bh, { glow: true });
          UI.txt(name, bx + 18, by + 14, { size: 16, color: EG.COLORS.gold, weight: 'bold', serif: true });
          UI.txt(`${EG.fmt(self.state.gold)} oro`, bx + bw - 18, by + 17, { size: 13, color: EG.COLORS.gold, align: 'right' });
          const tabY = by + 44;
          ['Comprar', 'Vender'].forEach((t, i) => {
            const tw = 96;
            const tx = bx + 18 + i * (tw + 8);
            const active = (i === 0 && tab === 'buy') || (i === 1 && tab === 'sell');
            ctx.save();
            EG.roundRect(ctx, tx, tabY, tw, 30, 8);
            ctx.fillStyle = active ? 'rgba(232,198,106,0.2)' : 'rgba(255,255,255,0.05)';
            ctx.fill();
            ctx.strokeStyle = active ? EG.COLORS.gold : 'rgba(140,150,180,0.3)';
            ctx.stroke();
            ctx.restore();
            UI.txt(t, tx + tw / 2, tabY + 8, { size: 12.5, color: active ? '#f2e3b6' : '#9aa3bd', align: 'center', weight: 'bold' });
            UI.region(tx, tabY, tw, 30, () => {
              tab = i === 0 ? 'buy' : 'sell';
              focus = 0; scroll = 0;
              EG.Audio.sfx('cursor');
            });
          });

          const list = this.list();
          const listY = tabY + 44;
          const rowH = 50;
          const vis = Math.max(1, Math.floor((by + bh - listY - 40) / rowH));
          if (focus < scroll) scroll = focus;
          if (focus >= scroll + vis) scroll = focus - vis + 1;
          list.slice(scroll, scroll + vis).forEach((it, i) => {
            const idx = scroll + i;
            const y = listY + i * rowH;
            const focused = idx === focus;
            ctx.save();
            EG.roundRect(ctx, bx + 12, y, bw - 24, rowH - 4, 8);
            ctx.fillStyle = focused ? 'rgba(232,198,106,0.12)' : 'rgba(255,255,255,0.03)';
            ctx.fill();
            ctx.restore();
            UI.txt(it.label, bx + 26, y + 8, { size: 13.5, color: '#f0ead8', weight: 'bold' });
            UI.txt(it.sub || '', bx + 26, y + 27, { size: 10.5, color: '#9aa3bd' });
            UI.txt(it.right, bx + bw - 26, y + 14, {
              size: 12, color: tab === 'buy' && self.state.gold < it.price ? '#e06060' : EG.COLORS.gold,
              align: 'right', weight: 'bold',
            });
            UI.region(bx + 12, y, bw - 24, rowH - 4, () => { focus = idx; this.activate(it); });
          });
          UI.txt(tab === 'buy' ? '◀ ▶ cambiar pestaña · A comprar · B salir' : '◀ ▶ cambiar pestaña · A vender · B salir', bx + bw / 2, by + bh - 22, {
            size: 10.5, color: 'rgba(200,210,235,0.45)', align: 'center',
          });
        },
      };
      this.openOverlay(overlay);
    },

    /* ------------------------------ FINAL ------------------------------ */

    ending() {
      this.mode = 'ending';
      this.endingTime = 0;
      this.overlays.length = 0;
      EG.Audio.stopMusic();
      EG.Audio.music('ending');
      this.state.flags.ending = true;
      this.autoSave();
    },

    updateEnding(dt) {
      this.endingTime += dt;
      const lines = this.endingLines();
      const total = lines.reduce((n, l) => n + (l.dur || 3), 0);
      if (this.endingTime > total + 2 || EG.Input.pressed('ok')) {
        if (EG.Input.pressed('ok') || this.endingTime > total + 8) {
          this.mode = 'title';
          this.titleTime = 0;
          this.state = null;
          EG.Audio.music('title');
        }
      }
    },

    endingLines() {
      const st = this.state || { playtime: 0, wins: 0 };
      return [
        { text: 'La Espada Celestial vuelve a brillar.', dur: 3.2 },
        { text: 'La luna respira. El eclipse se rompe como cristal.', dur: 3.2 },
        { text: 'Alba celebra. Brann duerme por primera vez en cien años.', dur: 3.2 },
        { text: 'Lyra escribe tu nombre en el margen de un mapa viejo.', dur: 3.2 },
        { text: 'Tú guardas la espada. No como rey, sino como promesa.', dur: 3.4 },
        { text: `Tiempo de juego: ${EG.clock(st.playtime || 0)}  ·  Victorias: ${st.wins || 0}`, dur: 3.6 },
        { text: 'FIN', dur: 4.2, big: true },
        { text: 'Gracias por jugar a LA ESPADA CELESTIAL.', dur: 3.2 },
        { text: 'Toca para volver al título.', dur: 20 },
      ];
    },

    drawEnding() {
      const UI = EG.UI, ctx = UI.ctx;
      const W = UI.W, H = UI.H;
      const t = this.endingTime;
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, '#0a1224');
      g.addColorStop(1, '#08060f');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
      // luna
      ctx.save();
      const glow = ctx.createRadialGradient(W / 2, H * 0.24, 10, W / 2, H * 0.24, Math.min(W, H) * 0.42);
      glow.addColorStop(0, 'rgba(240,232,200,0.22)');
      glow.addColorStop(1, 'rgba(240,232,200,0)');
      ctx.fillStyle = glow;
      ctx.fillRect(0, 0, W, H);
      ctx.beginPath();
      ctx.arc(W / 2, H * 0.24, Math.min(W, H) * 0.09, 0, Math.PI * 2);
      ctx.fillStyle = '#eae0c2';
      ctx.fill();
      ctx.restore();

      const lines = this.endingLines();
      let acc = 0;
      let current = null;
      for (const l of lines) {
        if (t >= acc && t < acc + l.dur) { current = l; break; }
        acc += l.dur;
      }
      if (current) {
        const local = t - acc;
        const a = Math.min(1, local * 2) * Math.min(1, (current.dur - local) * 1.6);
        ctx.save();
        ctx.globalAlpha = Math.max(0, Math.min(1, a));
        if (current.big) {
          UI.txt(current.text, W / 2, H * 0.52, {
            size: Math.min(64, W * 0.14), color: '#f2e3b6', align: 'center', baseline: 'middle', serif: true, weight: 'bold',
          });
        } else {
          const size = Math.min(20, W * 0.032);
          const linesWrapped = UI.wrap(current.text, W - 64, Math.max(15, size));
          linesWrapped.forEach((ln, i) => {
            UI.txt(ln, W / 2, H * 0.5 + (i - (linesWrapped.length - 1) / 2) * (size * 1.5), {
              size: Math.max(15, size), color: '#efe8d6', align: 'center', baseline: 'middle', serif: true,
            });
          });
        }
        ctx.restore();
      }
      EG.UI.hint('Toca o pulsa A para continuar');
    },

    /* ------------------------------- DEBUG ------------------------------- */

    debug: {
      giveAll() {
        const g = EG.game;
        for (const id of Object.keys(D().ITEMS)) g.addItem(id, 3);
        g.state.gold += 5000;
        EG.UI.showToast('Debug: objetos y oro');
      },
      warp(zone, x, y) {
        EG.game.state.fragments = Math.max(EG.game.state.fragments, zone === 'castillo' ? 2 : 0);
        EG.world.enter(zone, x, y, 'down');
        EG.game.mode = 'world';
      },
      battle(ids) {
        EG.game.startBattle(ids || ['limo'], { boss: false });
      },
      state() { return EG.game.state; },
    },
  };

  function statLine(stats) {
    const parts = [];
    const names = { atk: 'ATQ', def: 'DEF', mag: 'MAG', res: 'RES', spd: 'VEL', maxmp: 'PM' };
    for (const [k, v] of Object.entries(stats)) parts.push(`+${v} ${names[k] || k}`);
    return parts.join(' ');
  }

  EG.game = game;
  window.addEventListener('load', () => {
    try {
      game.init();
    } catch (err) {
      console.error(err);
      const msg = document.getElementById('boot-msg');
      if (msg) msg.textContent = 'Error al iniciar: ' + err.message;
    }
  });
})();

/* Historia, diálogos, misiones y jefes */
(function () {
  const EG = window.EG;
  const D = () => EG.data;
  const G = () => EG.game;
  const S = () => EG.game.state;

  const SPRITES = {
    Mira: 'elder', Dors: 'smith', Bruno: 'barkeep', Pía: 'girl',
    Lyra: 'lyra', Brann: 'brann', Ivo: 'merchant', Guardia: 'guard',
    Kael: 'kael', 'Lord Eclipse': 'knight', 'Araña Reina': 'knight',
  };

  function page(who, text, extra) {
    const p = { who: who || '', text };
    const sprite = SPRITES[who];
    if (sprite) p.sprite = sprite;
    return Object.assign(p, extra || {});
  }

  function dialog(pages, onEnd) {
    return EG.UI.dialog({ pages, onEnd });
  }

  function say(who, text, onEnd) {
    return dialog([page(who, text)], onEnd);
  }

  function join(id, levelBonus) {
    const st = S();
    if (st.party.some((p) => p.id === id)) return false;
    const lvl = Math.max(1, (st.party[0] ? st.party[0].lvl : 1) + (levelBonus || 0));
    st.party.push(D().newActor(id, lvl));
    return true;
  }

  function addFragments(n) {
    const st = S();
    st.fragments = Math.min(3, st.fragments + n);
    G().addItem('fragmento', n);
  }

  const story = {
    intro() {
      const st = S();
      st.quests.main = 'active';
      dialog([
        page('', 'Hace cien años, la Espada Celestial sostuvo la luna sobre el mundo. Hoy sólo quedan tres fragmentos… y un eclipse que no termina.'),
        page('Kael', 'Otra noche sin luna. El pozo está seco y los lobos bajan al camino.'),
        page('Mira', 'Kael. Ven. La espada que tu padre guardaba en la herrería ha empezado a cantar.'),
        page('Kael', '¿Cantar?'),
        page('Mira', 'Late. Como un corazón. Lord Eclipse ha despertado, y la espada sabe que es hora.'),
        page('Mira', 'Tres fragmentos, tres custodios: el Bosque de Sombras al oeste, las Ruinas de la Luna al este, el Castillo del Eclipse al sur.'),
        page('Kael', '¿Y si no vuelvo?'),
        page('Mira', 'Entonces la luna tampoco. Empieza por Dors, el herrero. Esa espada oxidada no te llevará lejos.'),
      ], () => {
        st.flags.intro = true;
        EG.UI.showToast('Objetivo: habla con la Anciana Mira', 'gold');
      });
    },

    talk(id, npc) {
      const st = S();
      const f = st.flags;

      if (id === 'mira') {
        if (!f.met_mira) {
          f.met_mira = true;
          st.quests.main = 'active';
          dialog([
            page('Mira', 'La espada no elige a los fuertes. Elige a los que vuelven.'),
            page('Mira', 'Lord Eclipse rompió la Espada Celestial hace cien años y se tragó su luz. Los fragmentos siguen vivos, pero sus custodios ya no distinguen amigos de intrusos.'),
            page('Mira', 'Busca el primero en el Bosque de Sombras. Dicen que una reina de seda lo custodia… y que una maga lleva días atrapada en sus hilos.'),
            page('Kael', '¿Cómo sé que podré?'),
            page('Mira', 'No lo sabrás. Por eso los héroes son tan raros.'),
          ], () => EG.UI.showToast('Misión principal actualizada: El primer fragmento', 'gold'));
          return;
        }
        if (st.fragments >= 3) {
          say('Mira', 'Los tres fragmentos cantan a la vez. La puerta del trono ya no te cerrará el paso. Termina esto, Kael.');
        } else if (st.fragments === 0) {
          say('Mira', 'El Bosque de Sombras está al oeste del Camino Real. No vayas solo: la maga atrapada en la seda sabe más de la luna que yo.');
        } else if (st.fragments === 1) {
          say('Mira', 'Siento el primer fragmento en tu mochila. El segundo duerme en las Ruinas de la Luna, al este. Brann, su último guardián, aún vive.');
        } else {
          say('Mira', 'Dos fragmentos. El tercero está en el Castillo del Eclipse, al sur. La puerta sólo reconoce la luz que llevas.');
        }
        return;
      }

      if (id === 'dors' || id === 'dors_tienda') {
        const stock = this.shopStock();
        if (!f.met_dors) {
          f.met_dors = true;
          st.quests.colmillos = 'active';
          dialog([
            page('Dors', '¿Esa espada? Tu padre la llamaba "la que espera". No sabía cuánto.'),
            page('Dors', 'Tráeme tres colmillos de lobo y te forjo algo que no dé vergüenza. Y compra pociones: morir es gratis, volver no.'),
          ], () => G().openShop('Herrería de Dors', stock));
          return;
        }
        if (st.quests.colmillos === 'active' && G().countItem('colmillo_lobo') >= 3) {
          G().addItem('colmillo_lobo', -3);
          st.gold += 400;
          G().addItem('espada_alba', 1);
          st.quests.colmillos = 'done';
          dialog([
            page('Dors', 'Tres colmillos. Limpios. Te has vuelto peligroso.'),
            page('Dors', 'Toma. Espada del Alba. No la he bautizado con agua: la he templado con la tuya.'),
          ], () => {
            EG.UI.showToast('+400 oro, +Espada del Alba', 'gold');
            G().openShop('Herrería de Dors', this.shopStock());
          });
          return;
        }
        G().openShop('Herrería de Dors', stock);
        return;
      }

      if (id === 'bruno' || id === 'bruno_posada') {
        const price = 25;
        dialog([
          page('Bruno', 'La cama está caliente y el caldo también. Veinticinco de oro y no preguntas por la mancha.'),
          page('Bruno', '¿Descansas?', {
            choices: [
              {
                label: `Descansar (${price} oro)`,
                action: () => {
                  if (S().gold < price) {
                    say('Bruno', 'Sin oro no hay caldo. Pero hoy tengo el corazón blando: pasa, que la luna ya nos debe bastante a todos.');
                    G().healParty();
                    G().saveTo('auto');
                    return;
                  }
                  S().gold -= price;
                  G().healParty();
                  G().saveTo('auto');
                  dialog([
                    page('Bruno', 'Duerme. Si sueñas con la luna, no le cuentes nada a Mira: se preocupa.'),
                  ], () => EG.UI.showToast('PV y PM restaurados · partida guardada', 'gold'));
                },
              },
              { label: 'Seguir viaje', action: () => {} },
            ],
          }),
        ]);
        return;
      }

      if (id === 'pia') {
        if (st.quests.flores === 'locked') {
          st.quests.flores = 'active';
          dialog([
            page('Pía', 'Las flores lunares sólo salen cuando la luna está triste. Y llevo tres noches sin ver ninguna.'),
            page('Pía', 'Mi madre dice que crecen en el Bosque de Sombras. ¿Me traes tres? Te daré lo que guardo para cuando sea mayor.'),
          ], () => EG.UI.showToast('Misión secundaria: Flores para Pía', 'gold'));
          return;
        }
        if (st.quests.flores === 'active') {
          const n = G().countItem('flor_lunar');
          if (n >= 3) {
            G().addItem('flor_lunar', -3);
            st.gold += 150;
            G().addItem('elixir', 1);
            st.quests.flores = 'done';
            dialog([
              page('Pía', '¡Son ellas! Huelen a ventana abierta.'),
              page('Pía', 'Toma. Mi madre dice que este elixir revive a cualquiera. Menos a los cobardes, dice.'),
            ], () => EG.UI.showToast('+150 oro, +Elixir', 'gold'));
          } else {
            say('Pía', `Llevas ${n} de 3 flores lunares. Se esconden entre la hierba alta del bosque.`);
          }
          return;
        }
        say('Pía', 'Cuando sea mayor voy a ser guardiana de la luna. O panadera. Aún lo pienso.');
        return;
      }

      if (id === 'guard') {
        if (st.fragments < 2) {
          say('Guardia', 'El Castillo del Eclipse está al sur. No dejo pasar a quien no lleve dos fragmentos: la puerta se alimenta de luz y devuelve huesos.');
        } else {
          say('Guardia', 'Dos fragmentos. Nunca pensé que diría esto, pero abre paso. Que la luna te vea.');
        }
        return;
      }

      if (id === 'ivo') {
        dialog([
          page('Ivo', '¿Sabes lo bueno de los monstruos? Tienen debilidades. Lo malo: también tienen dientes.'),
          page('Ivo', 'Limos y arañas odian el fuego. Murciélagos y esqueletos temen la luz. Los gólems se caen con un buen rayo.'),
          page('Ivo', 'Vendo pociones, éter y alguna cosa que no preguntarás de dónde sale.', {
            choices: [
              { label: 'Ver mercancía', action: () => G().openShop('Mercader Ivo', ['pocion', 'pocion_mayor', 'eter', 'antidoto', 'bomba']) },
              { label: 'Seguir camino', action: () => {} },
            ],
          }),
        ]);
        return;
      }

      if (id === 'lyra_web') {
        if (f.lyra_join) {
          say('Lyra', 'No mires así. Las telarañas eran parte del plan. Un plan muy malo, pero plan al fin y al cabo.');
          return;
        }
        dialog([
          page('Kael', 'Hay alguien dentro de la seda.'),
          page('Lyra', '¡Corta por la izquierda! La reina siente las vibraciones…'),
          page('Kael', '¿La reina?'),
          page('Lyra', 'La Araña Reina. Custodia el primer fragmento desde antes de que tu abuela naciera. Y yo llevo tres días colgada aquí.'),
          page('Lyra', 'Me llamo Lyra. Si vamos a morir, prefiero que sea en el mismo sitio.'),
          page('Lyra', 'El santuario está al sur, entre los pilares. Cuando la reina caiga, el fragmento será tuyo.'),
        ], () => {
          f.lyra_join = true;
          join('lyra', 1);
          EG.Audio.sfx('level');
          EG.UI.showToast('Lyra se une al grupo', 'gold');
          G().autoSave();
        });
        return;
      }

      if (id === 'brann') {
        if (f.brann_join) {
          say('Brann', 'Sigue adelante. Yo vigilo la entrada. Si algo sale de la oscuridad, saldrá cojo.');
          return;
        }
        dialog([
          page('Brann', 'Alto. Las Ruinas no perdonan a los vivos.'),
          page('Kael', 'Busco el segundo fragmento.'),
          page('Brann', 'Todos lo buscan. Yo lo custodié cien años y ni así lo entendí.'),
          page('Brann', 'El Guardián de la Luna duerme tras el sello. Robaste el Sello a la reina de la seda, ¿verdad? Entonces ábrelo tú.'),
          page('Brann', 'No puedo mirar. Pero puedo cubrirte la espalda.'),
        ], () => {
          f.brann_join = true;
          join('brann', 1);
          EG.Audio.sfx('level');
          EG.UI.showToast('Brann se une al grupo', 'gold');
          G().autoSave();
        });
        return;
      }

      say('', 'No hay nada que decir.');
    },

    shopStock() {
      const st = S();
      const f = st.flags;
      const goods = ['pocion', 'pocion_mayor', 'eter', 'antidoto', 'cuero_reforzado', 'baston_aprendiz', 'bota_viento'];
      if (f.frag1) goods.push('espada_alba', 'cota_malla', 'amuleto_luz');
      if (f.frag2) goods.push('tunica_lunar', 'anillo_poder', 'filo_lunar');
      if (f.frag3) goods.push('placas_luna', 'talisman_luna');
      return goods;
    },

    checkFlowers() {
      const st = S();
      if (st.quests.flores === 'active' && G().countItem('flor_lunar') >= 3) {
        EG.UI.showToast('Tienes 3 flores lunares. Vuelve con Pía en Alba.', 'gold');
      }
    },

    journal(st) {
      const f = st.flags;
      const items = [];
      let mainText;
      if (!f.met_mira) mainText = 'Habla con la Anciana Mira en la plaza de Alba.';
      else if (st.fragments === 0) mainText = 'Busca el primer fragmento en el Bosque de Sombras (oeste del Camino Real).';
      else if (st.fragments === 1) mainText = 'El segundo fragmento duerme en las Ruinas de la Luna (este).';
      else if (st.fragments === 2) mainText = 'El tercer fragmento está en el Castillo del Eclipse (sur).';
      else mainText = 'La puerta del trono está abierta. Derrota a Lord Eclipse.';
      items.push({
        label: 'La Espada Celestial',
        sub: mainText,
        right: `${st.fragments}/3`,
        color: EG.COLORS.gold,
        action: () => {},
      });
      items.push({
        label: 'Fragmentos recuperados',
        sub: f.frag1 ? 'I · Bosque de Sombras' : 'I · aún perdido',
        right: '',
        color: f.frag1 ? EG.COLORS.ink : '#5d6579',
        action: () => {},
      });
      items.push({
        label: '',
        sub: f.frag2 ? 'II · Ruinas de la Luna' : 'II · aún perdido',
        color: f.frag2 ? EG.COLORS.ink : '#5d6579',
        action: () => {},
      });
      items.push({
        label: '',
        sub: f.frag3 ? 'III · Castillo del Eclipse' : 'III · aún perdido',
        color: f.frag3 ? EG.COLORS.ink : '#5d6579',
        action: () => {},
      });
      if (st.quests.colmillos !== 'locked') {
        items.push({
          label: 'Colmillos para Dors',
          sub: st.quests.colmillos === 'done' ? 'Completada. La Espada del Alba es tuya.' : `Lleva 3 colmillos de lobo a Dors (${G().countItem('colmillo_lobo')}/3).`,
          right: st.quests.colmillos === 'done' ? '✓' : '',
          color: st.quests.colmillos === 'done' ? '#7fe89a' : EG.COLORS.ink,
          action: () => {},
        });
      }
      if (st.quests.flores !== 'locked') {
        items.push({
          label: 'Flores para Pía',
          sub: st.quests.flores === 'done' ? 'Completada. Pía guarda su elixir con orgullo.' : `Recoge 3 flores lunares en el bosque (${G().countItem('flor_lunar')}/3).`,
          right: st.quests.flores === 'done' ? '✓' : '',
          color: st.quests.flores === 'done' ? '#7fe89a' : EG.COLORS.ink,
          action: () => {},
        });
      }
      items.push({
        label: 'Valor',
        sub: `Victorias ${st.wins} · Derrotas ${st.deaths} · Tiempo ${EG.clock(st.playtime)}`,
        action: () => {},
      });
      return items;
    },

    runTrigger(script, trig) {
      const st = S();
      if (!script) return;
      if (script === 'boss_arana') {
        if (st.flags.frag1) { st.triggers[trig.id] = true; return; }
        dialog([
          page('', 'El santuario huele a seda vieja y a lluvia. Sobre el altar, un fragmento de luz late como un insecto atrapado.'),
          page('Lyra', 'Ahí está. Y ahí está ella.'),
          page('Araña Reina', 'Nadie toca lo que la luna me dejó.'),
          page('Kael', 'Aparta, o te aparto.'),
        ], () => {
          G().startBattle(['arana_reina'], {
            boss: true,
            onWin: () => {
              st.flags.frag1 = true;
              st.triggers[trig.id] = true;
              addFragments(1);
              EG.Audio.sfx('victory');
              dialog([
                page('', 'La reina cae y la seda se deshace como niebla. El fragmento flota hasta tu mano: pesa menos que una pluma y arde como una estrella.'),
                page('Kael', 'Uno.'),
                page('Lyra', 'Dos más. Y luego el hombre que se comió la luna.'),
                page('Lyra', 'Las Ruinas de la Luna están al este. Brann las guarda. Y Brann no ha dormido en cien años.'),
              ], () => EG.UI.showToast('Fragmento I recuperado', 'gold'));
            },
          });
        });
        return;
      }

      if (script === 'door_sello') {
        if (st.flags.door_sello) { st.triggers[trig.id] = true; return; }
        if (G().countItem('llave_ruinas') <= 0) {
          G().revertStep();
          say('', 'La puerta está sellada con una luna de piedra. Falta la pieza central: un sello antiguo, del tamaño de una mano.');
          return;
        }
        dialog([
          page('Kael', 'El Sello de la luna encaja. La piedra se abre como un párpado.'),
          page('Brann', 'Entra. Yo te sigo. Y no mires a los ojos a la estatua.'),
        ], () => {
          G().addItem('llave_ruinas', -1);
          st.flags.door_sello = true;
          st.triggers[trig.id] = true;
          EG.Audio.sfx('portal');
        });
        return;
      }

      if (script === 'boss_guardian') {
        if (st.flags.frag2) { st.triggers[trig.id] = true; return; }
        dialog([
          page('', 'La cámara está llena de polvo que no cae. En el centro, una estatua de piedra sostiene una media luna rota.'),
          page('Brann', 'Guardián. Soy Brann. He vuelto.'),
          page('', 'La estatua abre los ojos. No hay reconocimiento. Sólo el peso de cien años.'),
          page('Guardián de la Luna', 'NADIE TOCA LA LUNA.'),
        ], () => {
          G().startBattle(['guardian_luna'], {
            boss: true,
            onWin: () => {
              st.flags.frag2 = true;
              st.triggers[trig.id] = true;
              addFragments(1);
              dialog([
                page('', 'La piedra se agrieta y el segundo fragmento rueda hasta tus pies. Brann lo mira como quien mira una tumba abierta.'),
                page('Brann', 'Cien años. Y bastó una espada rota.'),
                page('Brann', 'Llévame contigo. No por la luna. Por ellos.'),
                page('Lyra', 'El Castillo del Eclipse está al sur. La puerta pide dos fragmentos. Ahora los tenemos.'),
              ], () => EG.UI.showToast('Fragmento II recuperado', 'gold'));
            },
          });
        });
        return;
      }

      if (script === 'boss_knight') {
        if (st.flags.frag3) { st.triggers[trig.id] = true; return; }
        dialog([
          page('', 'El salón del trono está vacío, salvo por una armadura que respira.'),
          page('Caballero Negro', 'El señor no recibe visitas.'),
          page('Brann', 'Esa armadura está vacía.'),
          page('Caballero Negro', 'También tu luna. Y sin embargo, la defiendes.'),
        ], () => {
          G().startBattle(['caballero_negro'], {
            boss: true,
            onWin: () => {
              st.flags.frag3 = true;
              st.triggers[trig.id] = true;
              addFragments(1);
              dialog([
                page('', 'La armadura se desmonta pieza a pieza. En su interior no hay nada, sólo un fragmento de luz que cae al suelo.'),
                page('Kael', 'Tres.'),
                page('Lyra', 'La puerta del trono ya reconoce tu luz. Detrás está Lord Eclipse.'),
                page('Brann', 'Y detrás de él, la luna. No falles.'),
              ], () => EG.UI.showToast('Fragmento III recuperado · el trono te espera', 'gold'));
            },
          });
        });
        return;
      }

      if (script === 'boss_lord') {
        if (st.flags.ending) return;
        dialog([
          page('', 'El trono flota sobre un pozo de noche. Lord Eclipse se vuelve despacio, como si el tiempo le costara.'),
          page('Lord Eclipse', 'La luz es un préstamo. Yo sólo cobro intereses.'),
          page('Kael', 'Devuelve la luna.'),
          page('Lord Eclipse', '¿Y quién me devuelve a mí? Cien años de sombra no se pagan con una espada bonita.'),
          page('Lord Eclipse', 'Ven. Te mostraré lo que queda de la luz cuando se le quita la esperanza.'),
        ], () => {
          G().startBattle(['lord_eclipse'], {
            boss: true,
            onWin: () => {
              st.flags.frag3 = true;
              st.triggers[trig.id] = true;
              dialog([
                page('', 'Lord Eclipse se deshace en una lluvia de ceniza fría. El último fragmento vuela de su pecho a tu espada.'),
                page('Kael', 'Se acabó.'),
                page('Lyra', 'No del todo. Mira.'),
                page('', 'La luna se enciende sobre el castillo, y por primera vez en cien años, el cielo tiene fondo.'),
              ], () => G().ending());
            },
          });
        });
        return;
      }
    },
  };

  EG.story = story;
})();

