  UI.txt('ELIGE OBJETIVO', p.x + 16, p.y + 12, { size: 12, color: '#e8c66a', weight: 'bold' });
  if (t) {
    UI.txt(t.name, p.x + 16, p.y + 30, { size: 16, color: '#f0ead8', weight: 'bold' });
    if (t.side === 'enemy') {
